const transcriptionListActiveQueue = `-- name: TranscriptionListActiveQueue :many
WITH ranked_queue AS (
  SELECT q."id", q."documentId",
         q."priority" + (EXTRACT(EPOCH FROM (NOW() - q."createdAt")) / 60)::int AS effective_priority,
         ROW_NUMBER() OVER (PARTITION BY d."repositoryId" ORDER BY q."createdAt" ASC) AS repo_rank,
         q."createdAt"
  FROM "TranscriptionJob" q
  JOIN "Document" d ON d.id = q."documentId"
  JOIN "Repository" r ON r.id = d."repositoryId"
  WHERE q."status" = 'QUEUED'
    AND r."transcriptionPaused" = false
)
SELECT "id", "documentId"
FROM ranked_queue
ORDER BY
  effective_priority DESC,
  repo_rank ASC,
  "createdAt" ASC
`

type TranscriptionListActiveQueueRow struct {
	ID         string `db:"id" json:"id"`
	DocumentId string `db:"documentId" json:"documentId"`
}

// 排队快照（只读，无锁）：与 TranscriptionClaimNextJobs 同口径的有效优先级排序与
// 仓级暂停过滤，供 ingest-status 计算每个 QUEUED 任务的排队位置。
func (q *Queries) TranscriptionListActiveQueue(ctx context.Context) ([]TranscriptionListActiveQueueRow, error) {
	rows, err := q.db.Query(ctx, transcriptionListActiveQueue)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TranscriptionListActiveQueueRow
	for rows.Next() {
		var i TranscriptionListActiveQueueRow
		if err := rows.Scan(&i.ID, &i.DocumentId); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const transcriptionPrioritizeJob = `-- name: TranscriptionPrioritizeJob :execrows
INSERT INTO "TranscriptionJob" (
  "id", "documentId", "requestedBy", "priority", "status", "options", "createdAt", "updatedAt"
)
VALUES (
  gen_random_uuid()::text, $1::text, $2::text, $3::int, 'QUEUED', '{}'::jsonb, NOW(), NOW()
)
ON CONFLICT ("documentId") DO UPDATE SET
  "priority" = CASE 
    WHEN "TranscriptionJob"."status" = 'RUNNING' THEN "TranscriptionJob"."priority"
    WHEN "TranscriptionJob"."status" = 'QUEUED' THEN GREATEST("TranscriptionJob"."priority", EXCLUDED."priority")
    ELSE EXCLUDED."priority"
  END,
  "status" = CASE 
    WHEN "TranscriptionJob"."status" = 'RUNNING' THEN 'RUNNING'
    ELSE 'QUEUED'
  END,
  "lastError" = CASE 
    WHEN "TranscriptionJob"."status" = 'RUNNING' THEN "TranscriptionJob"."lastError"
    ELSE NULL
  END,
  "finishedAt" = CASE 
    WHEN "TranscriptionJob"."status" = 'RUNNING' THEN "TranscriptionJob"."finishedAt"
    ELSE NULL
  END,
  "updatedAt" = CASE 
    WHEN "TranscriptionJob"."status" = 'RUNNING' THEN "TranscriptionJob"."updatedAt"
    ELSE NOW()
  END
`

type TranscriptionPrioritizeJobParams struct {
	DocumentID  string `db:"document_id" json:"document_id"`
	RequestedBy string `db:"requested_by" json:"requested_by"`
	Priority    int32  `db:"priority" json:"priority"`
}

func (q *Queries) TranscriptionPrioritizeJob(ctx context.Context, arg TranscriptionPrioritizeJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, transcriptionPrioritizeJob, arg.DocumentID, arg.RequestedBy, arg.Priority)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const transcriptionReapStaleJobs = `-- name: TranscriptionReapStaleJobs :one
WITH stale_jobs AS (
    SELECT "TranscriptionJob".id, "TranscriptionJob"."documentId", "TranscriptionJob".attempts
    FROM "TranscriptionJob"
    WHERE "TranscriptionJob"."status" = 'RUNNING'
      AND COALESCE("TranscriptionJob"."updatedAt", "TranscriptionJob"."claimedAt") < $1
),
requeued_jobs AS (
    update "TranscriptionJob"
    SET "status" = 'QUEUED',
        attempts = "TranscriptionJob".attempts + 1,
        "claimedAt" = NULL,
        "updatedAt" = now()
    FROM stale_jobs s
    WHERE "TranscriptionJob".id = s.id
      AND "TranscriptionJob"."status" = 'RUNNING'
      AND s.attempts + 1 < 3
    RETURNING "TranscriptionJob".id
),
failed_jobs AS (
    update "TranscriptionJob"
    SET "status" = 'FAILED',
        attempts = "TranscriptionJob".attempts + 1,
        "lastError" = 'Stale execution lease expired (exceeded 3 retry attempts)',
        "finishedAt" = now(),
        "updatedAt" = now()
    FROM stale_jobs s
    WHERE "TranscriptionJob".id = s.id
      AND "TranscriptionJob"."status" = 'RUNNING'
      AND s.attempts + 1 >= 3
    RETURNING "TranscriptionJob".id, "TranscriptionJob"."documentId"
),
failed_docs AS (
    UPDATE "Document"
    SET status = 'ERROR',
        "errorMessage" = 'Transcription job timed out after 3 retry attempts',
        "updatedAt" = now()
    FROM failed_jobs f
    WHERE "Document".id = f."documentId"
      AND "Document".status != 'PROCESSED'
    RETURNING "Document".id
)
SELECT ((SELECT count(*) FROM requeued_jobs) + (SELECT count(*) FROM failed_jobs))::bigint
`

func (q *Queries) TranscriptionReapStaleJobs(ctx context.Context, updatedat pgtype.Timestamp) (int64, error) {
	row := q.db.QueryRow(ctx, transcriptionReapStaleJobs, updatedat)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const transcriptionRecentAvgJobSeconds = `-- name: TranscriptionRecentAvgJobSeconds :one
SELECT COALESCE(
  AVG(EXTRACT(EPOCH FROM (j."finishedAt" - j."claimedAt"))),
  -1
)::float8
FROM (
  SELECT "finishedAt", "claimedAt"
  FROM "TranscriptionJob"
  WHERE "status" = 'DONE' AND "finishedAt" IS NOT NULL AND "claimedAt" IS NOT NULL
  ORDER BY "finishedAt" DESC
  LIMIT 20
) j
`

// 最近 20 个 DONE 任务的平均执行耗时（claimedAt→finishedAt 秒）；无历史返回 -1 哨兵。
func (q *Queries) TranscriptionRecentAvgJobSeconds(ctx context.Context) (float64, error) {
	row := q.db.QueryRow(ctx, transcriptionRecentAvgJobSeconds)
	var column_1 float64
	err := row.Scan(&column_1)
	return column_1, err
}

